import { test, expect } from '@playwright/test';

test.describe('Conflict Error Message on Stale Record Save', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display conflict error when saving a stale record', async ({ page }) => {
    // Setup: intercept the initial GET request
    await page.route('**/api/records/123', route => {
      route.continue();
    });

    // Setup: intercept the PUT request with conflict response
    await page.route('**/api/records/123', route => {
      route.abort('failed');
      route.continue();
    });

    // Get the record form using getByRole
    const recordForm = page.getByRole('form', { name: /record form/i });
    await expect(recordForm).toBeVisible();

    // Fill in form fields using getByLabel
    const titleInput = page.getByLabel(/title/i);
    await titleInput.fill('Updated Title');

    const descriptionInput = page.getByLabel(/description/i);
    await descriptionInput.fill('Updated description');

    // Get the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Click save button
    await saveButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/conflict error: record has been modified by another user/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message styling
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify form is still visible
    await expect(recordForm).toBeVisible();
  });

  test('should allow user to retry save after conflict error', async ({ page }) => {
    // Setup: intercept the initial GET request
    await page.route('**/api/records/123', route => {
      route.continue();
    });

    // Setup: intercept the first PUT request with conflict response
    let attempt = 0;
    await page.route('**/api/records/123', route => {
      attempt++;
      if (attempt === 1) {
        route.abort('failed');
        route.continue();
      } else {
        route.continue();
      }
    });

    // Get the record form using getByRole
    const recordForm = page.getByRole('form', { name: /record form/i });
    await expect(recordForm).toBeVisible();

    // Fill in form fields using getByLabel
    const titleInput = page.getByLabel(/title/i);
    await titleInput.fill('New Title');

    const descriptionInput = page.getByLabel(/description/i);
    await descriptionInput.fill('New description');

    // Get the save button using getByRole
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Click save button (first attempt - should fail)
    await saveButton.click();

    // Verify conflict error message appears
    const errorMessage = page.getByText(/conflict error: record has been modified by another user/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Wait for retry request to complete
    await page.waitForResponse(response =>
      response.url().includes('/api/records/123') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText(/record saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });
});
